  flatMap: (res, fn) => (res && typeof res === "object" && res.$tag === "Ok" && typeof fn === "function" ? fn(res.val) : res),
  flatten: (res) => (res && typeof res === "object" && res.$tag === "Ok" ? res.val : res),
