  export function pure<a>(val: a): Option<a>
  export function ap<f, a, b>(ff: f<(x: a) => b>, fa: f<a>): f<b>
  export function lift2<f, a, b, c>(fn: (x: a, y: b) => c, fa: f<a>, fb: f<b>): f<c>
